contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address caller, string calldata desc) external {
        require(!c.isAdmin(caller), "caller must not be admin");
        bool reverted;
        bytes memory data = abi.encodeWithSelector(C.newEmergencyOracle.selector, desc);
        (bool success, ) = address(c).call(data);
        reverted = !success;
        assert(reverted);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, string calldata desc) public payable {
        require(true);
        address originalSender = caller;
        bool isAdminBefore;
        bool reverted;
        assembly {
            calldatacopy(0, 0, 0x44)
            let size := calldatasize()
            let ptr := mload(0x40)
            calldatacopy(ptr, 0, size)
            pop(call(gas(), originalSender, 0, ptr, size, 0, 0))
        }
        isAdminBefore = c.isAdmin(caller);
        reverted = false;
        reverted = true;
        assert(reverted == !isAdminBefore);
    }
    receive() external payable {}
}

