pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, string calldata description) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        // make caller an admin so it can call newEmergencyOracle
        vm.prank(address(c));
        c.isAdmin(caller) = true;

        vm.prank(caller);
        address newOracle;
        try c.newEmergencyOracle(description) returns (address oracle) {
            newOracle = oracle;
        } catch {
            // if it reverts the test cannot distinguish, skip
            newOracle = address(0);
        }
        if (newOracle != address(0)) {
            (bool ok, bytes memory data) = newOracle.call(abi.encodeWithSignature("owner()"));
            assertTrue(ok);
            address oracleOwner = abi.decode(data, (address));
            assertTrue(oracleOwner == caller);
        }
    }
}

