pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, string calldata description) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        c.isAdmin(caller); // ensure caller is admin
        // make caller admin
        vm.startPrank(address(this));
        c.isAdmin(caller) = true; // set admin
        vm.stopPrank();
        vm.prank(caller);
        try c.newEmergencyOracle(description) returns (address oracle) {
            // After deployment, owner() of the new oracle must equal caller
            (bool success, bytes memory data) = oracle.call(abi.encodeWithSignature("owner()"));
            require(success, "owner() call failed");
            address oracleOwner = abi.decode(data, (address));
            assertEq(oracleOwner, caller);
        } catch {
            assertTrue(false, "newEmergencyOracle reverted unexpectedly");
        }
    }
}
